package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("price_history") public class PriceHistory {@Id private String id;@Indexed private String itemType;@Indexed private String itemId;private double basePrice;private double currentPrice;private double multiplier;private String reason;@Indexed private Instant timestamp=Instant.now();public String getId(){return id;}public String getItemType(){return itemType;}public void setItemType(String x){itemType=x;}public String getItemId(){return itemId;}public void setItemId(String x){itemId=x;}public double getBasePrice(){return basePrice;}public void setBasePrice(double x){basePrice=x;}public double getCurrentPrice(){return currentPrice;}public void setCurrentPrice(double x){currentPrice=x;}public double getMultiplier(){return multiplier;}public void setMultiplier(double x){multiplier=x;}public String getReason(){return reason;}public void setReason(String x){reason=x;}public Instant getTimestamp(){return timestamp;}public void setTimestamp(Instant x){timestamp=x;}}
